var t=75;var a=[{id:`cooking-075-01`,theoryId:75,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What happens when too much cold food is added to a fryer?`,ua:`Що відбувається, якщо додати до фритюру забагато холодних продуктів?`},explanation:{en:`Food absorbs heat faster than the fryer may restore it.`,ua:`Продукти поглинають тепло швидше, ніж фритюрниця може його відновити.`},options:[{id:`a`,text:{en:`Oil temperature may fall and browning slows`,ua:`Температура олії може впасти, а підрум’янення сповільнитися`}},{id:`b`,text:{en:`Oil instantly becomes colder than ice`,ua:`Олія миттєво стає холоднішою за лід`}},{id:`c`,text:{en:`The food becomes sterile immediately`,ua:`Продукт миттєво стає стерильним`}}],answer:{optionIds:[`a`]}},{id:`cooking-075-02`,theoryId:75,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Pouring water onto burning cooking oil is a safe way to extinguish the fire.`,ua:`Заливати водою палаючу кулінарну олію — безпечний спосіб загасити вогонь.`},explanation:{en:`Water can cause burning oil to erupt and spread; follow fire-safety procedures.`,ua:`Вода може викинути палаючу олію й поширити полум’я; дійте за правилами пожежної безпеки.`},answer:{value:!1}},{id:`cooking-075-03`,theoryId:75,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match frying symptoms to likely causes.`,ua:`Поєднайте ознаки фритюру з імовірними причинами.`},explanation:{en:`Temperature, coating and load affect deep-frying results.`,ua:`Температура, панірування та кількість продуктів впливають на результат.`},leftItems:[{id:`l1`,text:{en:`Oil smokes excessively`,ua:`Олія сильно димить`}},{id:`l2`,text:{en:`Coating falls off`,ua:`Панірування відпадає`}},{id:`l3`,text:{en:`Food is greasy and pale`,ua:`Продукт жирний та блідий`}}],rightItems:[{id:`r3`,text:{en:`Oil may be too cool or fryer overcrowded`,ua:`Олія може бути надто холодною або фритюр переповнений`}},{id:`r2`,text:{en:`Poor adhesion or handling`,ua:`Погане прилипання чи необережне поводження`}},{id:`r1`,text:{en:`Excessive heat or degraded oil`,ua:`Надмірний нагрів або зношена олія`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-075-04`,theoryId:75,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A pan of frying oil catches fire. What should you do first if you can act safely?`,ua:`У сковороді загорілася олія. Що зробити насамперед, якщо діяти безпечно?`},explanation:{en:`Do not move burning oil or use water; prioritize evacuation if it cannot be controlled safely.`,ua:`Не переносіть палаючу олію й не використовуйте воду; якщо пожежу не можна безпечно локалізувати, евакуюйтесь.`},options:[{id:`a`,text:{en:`Turn off heat and smother a small contained fire with a suitable metal lid; call emergency services if needed`,ua:`Вимкнути нагрів і накрити невелике локальне полум’я відповідною металевою кришкою; за потреби викликати пожежників`}},{id:`b`,text:{en:`Carry the burning pan outdoors`,ua:`Понести палаючу сковороду надвір`}},{id:`c`,text:{en:`Pour a bucket of water into the pan`,ua:`Вилити відро води у сковороду`}}],answer:{optionIds:[`a`]}},{id:`cooking-075-05`,theoryId:75,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which action increases hot-oil injury risk?`,ua:`Яка дія підвищує ризик травмування гарячою олією?`},explanation:{en:`Overfilling increases dangerous overflow and splashing risk.`,ua:`Переповнення підвищує ризик переливання та небезпечного розбризкування.`},options:[{id:`a`,text:{en:`Dry food surface before frying`,ua:`Обсушити поверхню продуктів перед смаженням`}},{id:`b`,text:{en:`Lower food gently using suitable tools`,ua:`Обережно занурювати продукти відповідними інструментами`}},{id:`c`,text:{en:`Fill the fryer above its maximum line`,ua:`Заповнити фритюрницю вище максимальної позначки`}}],answer:{optionIds:[`c`]}},{id:`cooking-075-06`,theoryId:75,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which practices improve deep-frying safety?`,ua:`Які практики підвищують безпечність фритюру?`},explanation:{en:`Water, overfilling and unattended heating all increase serious injury risk.`,ua:`Вода, переповнення й нагрівання без нагляду підвищують ризик травм.`},options:[{id:`a`,text:{en:`Keep water away from hot oil`,ua:`Не допускати потрапляння води у гарячу олію`}},{id:`b`,text:{en:`Respect the fryer fill limit`,ua:`Дотримуватися межі заповнення фритюрниці`}},{id:`c`,text:{en:`Never leave heating oil unattended`,ua:`Не залишати гарячу олію без нагляду`}},{id:`d`,text:{en:`Extinguish oil fire by pouring water`,ua:`Гасити палаючу олію водою`}}],answer:{optionIds:[`a`,`b`,`c`]}},{id:`cooking-075-07`,theoryId:75,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A fryer holds 2,000 mL of cooking oil within the manufacturer’s safe fill limit. You add another 250 mL of oil (without heating). What is the new total volume in milliliters?`,ua:`У фритюрниці є 2000 мл олії в межах безпечного рівня виробника. Ви доливаєте ще 250 мл (без нагрівання). Який новий загальний об’єм у мілілітрах?`},explanation:{en:`2000 + 250 = 2250 mL; always confirm the final fill remains within the manufacturer’s limit.`,ua:`2000 + 250 = 2250 мл; обов’язково перевірте, чи не перевищено дозволений рівень заповнення.`},numericInput:{unit:`mL`,unitLabel:{en:`milliliters`,ua:`мілілітрів`},allowDecimals:!1},answer:{value:2250,tolerance:0,unit:`mL`}}];var n={theoryId:75,exercises:a};export{n as default,a as exercises,t as theoryId};